<?php
require_once __DIR__ . '/../includes/bootstrap.php'; require_admin(); $pageTitle='Student management'; $errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=(string)($_POST['action']??'');
 try { $conn=db();
  if ($action==='save') { $id=(int)($_POST['id']??0); $name=trim((string)($_POST['full_name']??'')); $email=trim((string)($_POST['email']??'')); $mobile=trim((string)($_POST['mobile']??'')); $course=trim((string)($_POST['course']??'')); $year=(int)($_POST['year_of_study']??0);
   if(!preg_match("/^[\\p{L}][\\p{L} .'-]{1,79}$/u",$name)) $errors[]='Enter a valid student name.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL)) $errors[]='Enter a valid email.'; if(!preg_match('/^[6-9][0-9]{9}$/',$mobile)) $errors[]='Enter a valid 10-digit mobile number.'; if($course==='') $errors[]='Course is required.'; if($year<1||$year>4) $errors[]='Year must be between 1 and 4.';
   if(!$errors) { if($id>0) { $stmt=$conn->prepare('UPDATE students SET full_name=?,email=?,mobile=?,course=?,year_of_study=? WHERE id=?'); $stmt->bind_param('ssssii',$name,$email,$mobile,$course,$year,$id); $stmt->execute(); flash('success','Student record updated.'); } else { $stmt=$conn->prepare('INSERT INTO students (full_name,email,mobile,course,year_of_study) VALUES (?,?,?,?,?)'); $stmt->bind_param('ssssi',$name,$email,$mobile,$course,$year); $stmt->execute(); flash('success','Student record added.'); } redirect('admin/students.php'); }
  } elseif($action==='delete') { $id=(int)($_POST['id']??0); $stmt=$conn->prepare('DELETE FROM students WHERE id=?'); $stmt->bind_param('i',$id); $stmt->execute(); flash('success','Student record deleted.'); redirect('admin/students.php'); }
 } catch(Throwable $ex) { error_log('Student CRUD: '.$ex->getMessage()); $errors[]='The operation failed. Check duplicate email constraints and try again.'; }
}
$edit=null; if(isset($_GET['edit'])) { try{$conn=db();$id=(int)$_GET['edit'];$stmt=$conn->prepare('SELECT * FROM students WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$edit=$stmt->get_result()->fetch_assoc();}catch(Throwable $ex){$errors[]='Could not load that student.';} }
$q=trim((string)($_GET['q']??''));$courseFilter=trim((string)($_GET['course']??''));$yearFilter=(int)($_GET['year']??0);$students=[];
try { $conn=db(); $sql='SELECT s.*,u.username FROM students s LEFT JOIN users u ON u.id=s.user_id WHERE (s.full_name LIKE ? OR s.email LIKE ? OR s.mobile LIKE ?)'; $like='%'.$q.'%'; $types='sss';$params=[$like,$like,$like]; if($courseFilter!==''){$sql.=' AND s.course=?';$types.='s';$params[]=$courseFilter;} if($yearFilter>=1&&$yearFilter<=4){$sql.=' AND s.year_of_study=?';$types.='i';$params[]=$yearFilter;} $sql.=' ORDER BY s.created_at DESC';$stmt=$conn->prepare($sql);$stmt->execute($params);$students=$stmt->get_result()->fetch_all(MYSQLI_ASSOC); } catch(Throwable $ex) { $errors[]='Could not retrieve student records. Check the database setup.'; error_log('Student list: '.$ex->getMessage()); }
require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="container"><p class="eyebrow">Administrator workspace</p><h1>Student management.</h1><p class="lead">Create, view, update, delete, search and filter student records.</p></div></section><section class="section"><div class="container admin-layout"><?php require __DIR__.'/_sidebar.php'; ?><div><?php foreach($errors as $err): ?><div class="notice error mb-24" role="alert"><?=e($err)?></div><?php endforeach; ?><section class="panel mb-24"><h2><?= $edit?'Edit student':'Add student' ?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label for="full_name">Full name</label><input id="full_name" name="full_name" required maxlength="80" value="<?=e($edit['full_name']??'')?>"></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required maxlength="190" value="<?=e($edit['email']??'')?>"></div><div class="field"><label for="mobile">Mobile</label><input id="mobile" name="mobile" required pattern="[6-9][0-9]{9}" maxlength="10" value="<?=e($edit['mobile']??'')?>"></div><div class="field"><label for="course">Course</label><input id="course" name="course" required maxlength="100" value="<?=e($edit['course']??'')?>"></div><div class="field"><label for="year_of_study">Year of study</label><select id="year_of_study" name="year_of_study" required><?php for($i=1;$i<=4;$i++): ?><option value="<?=$i?>" <?= (int)($edit['year_of_study']??1)===$i?'selected':'' ?>>Year <?=$i?></option><?php endfor; ?></select></div></div><button class="button" type="submit"><?= $edit?'Save changes':'Add student' ?></button><?php if($edit): ?> <a class="button-secondary" href="<?=e(app_url('admin/students.php'))?>">Cancel edit</a><?php endif; ?></form></section><section class="panel"><h2>Student records (<?=count($students)?>)</h2><form class="toolbar" method="get"><label class="field" style="flex:2;margin:0"><span>Search</span><input name="q" value="<?=e($q)?>" placeholder="Name, email or mobile"></label><label class="field" style="margin:0"><span>Course</span><select name="course"><option value="">All courses</option><?php foreach(['Computer Engineering','Information Technology','Computer Science','Design','Business'] as $c): ?><option <?= $courseFilter===$c?'selected':'' ?> value="<?=e($c)?>"><?=e($c)?></option><?php endforeach; ?></select></label><label class="field" style="margin:0"><span>Year</span><select name="year"><option value="0">All years</option><?php for($i=1;$i<=4;$i++): ?><option value="<?=$i?>" <?= $yearFilter===$i?'selected':'' ?>>Year <?=$i?></option><?php endfor; ?></select></label><button class="button" type="submit">Apply</button></form><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Course</th><th>Year</th><th>Actions</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?=e($s['full_name'])?></td><td><?=e($s['username']??'—')?></td><td><?=e($s['email'])?></td><td><?=e($s['course'])?></td><td><?=e($s['year_of_study'])?></td><td><div class="table-actions"><a class="button-secondary button-small" href="<?=e(app_url('admin/students.php?edit='.(int)$s['id']))?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this student record?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($s['id'])?>"><button class="button-danger button-small" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?><?php if(!$students): ?><tr><td colspan="6">No matching student records.</td></tr><?php endif; ?></tbody></table></div></section></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
